// Finance operates on financial projections; technical controls keep their own guards.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opt=v=>v?.[0]??null;
const money=(n,c='')=>`${(BigInt(n)/100n).toLocaleString('en-CH')}.${String(BigInt(n)%100n).padStart(2,'0')} ${c}`.trim();
const inputMoney=n=>`${BigInt(n)/100n}.${String(BigInt(n)%100n).padStart(2,'0')}`;
const minor=s=>{if(!/^\d+(\.\d{1,2})?$/.test(String(s)))throw Error('Enter a positive amount with up to two decimals.');const[a,b='']=String(s).split('.');return BigInt(a)*100n+BigInt(b.padEnd(2,'0'));};
const today=()=>new Date().toISOString().slice(0,10);
const stamp=n=>new Date(Number(n/1000000n)).toLocaleString();
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const errorText=e=>e?.message||'This information is unavailable. Please retry.';
const bannerText=s=>!s?'Finance setup could not be checked.':s.mode==='it'?'':s.mode==='unconfigured'?'No Finance team is set. Choose who reviews payments, or keep this work with IT.':!s.enabled||!Number(s.activeMembers)?'Finance needs attention: this app has no active Finance recipients. Assets admins still manage payments.':'';
export async function financeBanner(root,{api,token,hubUrl}){
  if(!root)return;let status=null;try{status=opt(await api().financeSetup(token()));}catch{}
  const text=bannerText(status);root.innerHTML=text?`<aside class="card flat"><strong>Finance setup</strong><p>${esc(text)}</p><a href="${esc(hubUrl.replace(/\/$/,'')+'/#/settings/teams')}">Manage Finance in Hub →</a></aside>`:'';
}
export function createFinance(root,{api,token,hubUrl}){
  let generation=0,tab='payments',offset=0,asOf=today(),search='',overdue=false,missingOnly=false,data=null;
  const $=s=>root.querySelector(s);
  const status=text=>{if($('[data-f-status]'))$('[data-f-status]').textContent=text;};
  function frame(){root.innerHTML=`<div class="page-heading"><div><h2>Finance</h2><p class="lead">Review payments and keep hardware values current.</p></div><a href="#/sales">All sales →</a></div><div data-f-banner></div><nav class="stabs" aria-label="Finance workspace"><button class="stab ${tab==='payments'?'active':''}" data-tab="payments">Payments</button><button class="stab ${tab==='values'?'active':''}" data-tab="values">Hardware values</button></nav><div data-f-body aria-busy="true"><p role="status">Loading Finance…</p></div><p data-f-status role="status" aria-live="polite"></p>`;root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;offset=0;load();});financeBanner($('[data-f-banner]'),{api,token,hubUrl});}
  function pages(total,rows){return `<div class="btnrow"><span class="kv">${Number(total)} records${rows?` · ${offset+1}–${offset+rows}`:''}</span>${offset?'<button data-prev>Previous</button>':''}${offset+rows<Number(total)?'<button data-next>Next 100</button>':''}</div>`;}
  function wirePages(){if($('[data-prev]'))$('[data-prev]').onclick=()=>{offset=Math.max(0,offset-100);loadBody();};if($('[data-next]'))$('[data-next]').onclick=()=>{offset+=100;loadBody();};}
  async function loadBody(){const version=++generation;$('[data-f-body]').setAttribute('aria-busy','true');status('');try{
    if(tab==='payments'){
      const result=opt(await api().financePayments(token(),overdue,BigInt(offset)));if(version!==generation)return;if(!result)throw Error('Finance access is unavailable. Sign in again to refresh your permissions.');data=result;
      $('[data-f-body]').innerHTML=`<div class="finance-toolbar"><div class="btnrow"><button data-filter="all" aria-pressed="${!overdue}" class="${!overdue?'primary':''}">Open payments · ${result.open}</button><button data-filter="overdue" aria-pressed="${overdue}" class="${overdue?'primary':''}">Overdue · ${result.overdue}</button></div><button data-pay-export>Export payment history</button></div><p class="kv">Outstanding: ${result.totals.map(([c,n])=>esc(money(n,c))).join(' · ')||'No unpaid invoices'}</p><div class="card flat">${result.rows.map(r=>`<a class="finance-row" href="#/sale/${r.id}"><span><strong>${esc(r.number)} · ${esc(r.buyer)}</strong><small>${esc(r.device)} · Due ${esc(r.dueOn)}</small></span><strong>${esc(money(r.outstandingMinor,r.currency))}</strong></a>`).join('')||`<div class="empty">${overdue?'No overdue invoices.':'All issued invoices are paid. New invoices appear here automatically.'}</div>`}</div>${pages(result.matched,result.rows.length)}`;
      root.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{overdue=b.dataset.filter==='overdue';offset=0;loadBody();});
      $('[data-pay-export]').onclick=()=>run(async()=>download('payments.csv',await api().paymentsExportCsv(token())));
    }else{
      const result=opt(await api().financeInventory(token(),asOf,search,BigInt(offset)));if(version!==generation)return;if(!result)throw Error('Values are unavailable. Check the date and your Finance access.');data=result;
      $('[data-f-body]').innerHTML=`<div class="finance-toolbar"><label>Find hardware<input data-search type="search" placeholder="Device, tag or person" value="${esc(search)}"></label><label>Value at<input data-date type="date" value="${asOf}" required></label><button data-export>Export valuation</button></div><p class="kv">Current inventory, calculated at ${esc(asOf)}: ${result.totals.map(([c,n])=>esc(money(n,c))).join(' · ')||'No configured values'} · ${result.missing} missing or not yet in service. Sold, scrapped and archived hardware is excluded from totals.</p><div class="card flat">${result.rows.map(a=>`<a class="finance-row" href="#/finance/${a.id}"><span><strong>${esc(a.name)}</strong><small>${esc(a.tag||a.serial)} · ${esc(a.kind)} · ${esc(a.assignee||a.status)}${a.archived?' · archived':''}</small></span><span>${a.bookMinor.length?esc(money(a.bookMinor[0],opt(a.purchase)?.currency)):'Set valuation →'}</span></a>`).join('')||'<div class="empty">No hardware matches. Try its tag, serial or assigned person.</div>'}</div>${pages(result.matched,result.rows.length)}<details class="card flat"><summary>Useful-life defaults</summary><p class="kv">Choose your company’s straight-line useful life for each type. Existing valuations keep their agreed values. Depreciation starts the month after the in-service date and stops at the residual value. Book value is separate from the sale-price suggestion.</p><form data-defaults><div class="finance-form-grid">${['laptop','phone','tablet','monitor','accessory','other'].map(k=>`<label>${k[0].toUpperCase()+k.slice(1)} · months<input type="number" min="1" max="600" name="${k}" value="${result.defaults.find(d=>d.kind===k)?.months||''}" placeholder="Not configured"></label>`).join('')}</div><button class="primary">Save defaults</button></form></details>`;
      let timer;$('[data-search]').oninput=e=>{search=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{offset=0;loadBody();},350);};$('[data-date]').onchange=e=>{if(e.target.checkValidity()){asOf=e.target.value;offset=0;loadBody();}};
      $('[data-export]').onclick=()=>run(async()=>download(`hardware-values-${asOf}.csv`,await api().financeInventoryCsv(token(),asOf)));
      $('[data-defaults]').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),rows=[...f].filter(([,v])=>v!=='').map(([kind,months])=>({kind,months:BigInt(months)}));run(async()=>{const r=await api().setValuationDefaults(token(),result.defaultsRevision,rows);if(!r.ok)throw Error(r.detail);await loadBody();status(r.detail);});};
    }
    wirePages();
  }catch(e){if(version===generation){$('[data-f-body]').innerHTML='<div class="empty">Finance could not be loaded. <button data-retry>Retry</button></div>';$('[data-retry]').onclick=loadBody;status(errorText(e));}}finally{if(version===generation)$('[data-f-body]')?.removeAttribute('aria-busy');}}
  async function run(action){try{await action();}catch(e){status(errorText(e));}}
  async function asset(id){const version=++generation;root.innerHTML='<p role="status">Loading hardware valuation…</p>';try{
    const [result,inventory]=await Promise.all([api().financeAsset(token(),BigInt(id),asOf),api().financeInventory(token(),asOf,'',0n)]);if(version!==generation)return;const value=opt(result);if(!value)throw Error('This financial record is unavailable.');const a=value.asset,p=opt(a.purchase),v=opt(a.valuation)?.input,defaults=opt(inventory)?.defaults||[];
    root.innerHTML=`<a href="#/finance">‹ Finance</a><div class="page-heading"><div><h2>${esc(a.name)}</h2><p class="lead">${esc(a.tag||a.serial)} · ${esc(a.kind)} · ${esc(a.assignee||a.status)}</p></div><div><small>Book value · ${esc(asOf)}</small><p><strong>${a.bookMinor.length?esc(money(a.bookMinor[0],p?.currency)):'Not configured'}</strong></p></div></div><section class="card"><h3>Hardware valuation</h3><p class="kv">Straight-line depreciation starts in the month after the in-service date. This calculation uses the current valuation basis; it is not a historical inventory snapshot or a tax rule.</p><form data-value><div class="finance-form-grid"><label>Purchase cost<input name="priceMinor" inputmode="decimal" value="${p?inputMoney(p.priceMinor):''}" required></label><label>Currency<input name="currency" maxlength="3" pattern="[A-Z]{3}" value="${esc(p?.currency||'CHF')}" required></label><label>Purchased on<input name="purchasedOn" type="date" max="${today()}" value="${esc(p?.date||'')}" required></label><label>In service on<input name="inServiceOn" type="date" max="${today()}" value="${esc(v?.inServiceOn||p?.date||'')}" required></label><label>Useful life · months<input name="months" type="number" min="1" max="600" value="${v?.months||defaults.find(d=>d.kind===a.kind)?.months||''}" required></label><label>Residual value<input name="residualMinor" inputmode="decimal" value="${v?inputMoney(v.residualMinor):'0.00'}" required></label></div><label>Reason for this valuation<input name="reason" maxlength="500" placeholder="Purchase recorded, useful life agreed…" required></label><div class="btnrow"><button class="primary">Review valuation</button><a href="#/finance">Cancel</a></div><p data-f-status role="status" aria-live="polite"></p><div data-value-review></div></form></section><details class="card flat"><summary>Valuation history · ${value.history.length}</summary>${[...value.history].reverse().map(h=>`<p><strong>${esc(money(h.input.priceMinor,h.input.currency))} · ${h.input.months} months</strong><br>${esc(h.input.reason)}<br><small>${esc(h.by)} · ${esc(stamp(h.at))}</small></p>`).join('')||'<p>No valuation changes recorded yet.</p>'}</details>`;
    $('[data-value]').onsubmit=e=>{e.preventDefault();let input;try{const f=Object.fromEntries(new FormData(e.currentTarget));input={...f,priceMinor:minor(f.priceMinor),residualMinor:minor(f.residualMinor),months:BigInt(f.months)};}catch(e){status(errorText(e));return;}
      $('[data-value-review]').innerHTML=`<div class="card flat"><p>Save ${esc(money(input.priceMinor,input.currency))}, ${input.months} months and ${esc(money(input.residualMinor,input.currency))} residual value from ${esc(input.inServiceOn)}?</p><p class="kv">The purchase basis also updates future sale-price suggestions. Issued invoices remain unchanged.</p><button type="button" class="primary" data-save-value>Save valuation</button></div>`;
      const serialized=JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)));
      $('[data-save-value]').onclick=async()=>{if(JSON.stringify(Object.fromEntries(new FormData($('[data-value]'))))!==serialized){$('[data-value-review]').replaceChildren();status('Values changed. Review again before saving.');return;}root.querySelectorAll('input,button').forEach(x=>x.disabled=true);try{const r=await api().saveAssetValuation(token(),a.id,a.revision,input);if(!r.ok)throw Error(r.detail);await asset(id);status(r.detail);}catch(e){status(errorText(e));root.querySelectorAll('input,button').forEach(x=>x.disabled=false);}};
    };
  }catch(e){if(version===generation)root.innerHTML=`<a href="#/finance">‹ Finance</a><p role="alert">${esc(errorText(e))}</p>`;}}
  async function load(id){if(id)return asset(id);frame();await loadBody();}
  return {load};
}
export async function paymentPanel(root,{api,token,sale,reload,isCurrent=()=>true}){
  const s=sale;root.hidden=false;root.innerHTML='<h3>Payments</h3><p role="status">Loading payment history…</p>';
  try{
    const history=opt(await api().salePaymentHistory(token(),s.id));if(!history)throw Error('Payment history is unavailable. Refresh your sign-in.');if(!root.isConnected||!isCurrent())return;
    const notices=await api().saleFinanceNotification(token(),s.id);if(!isCurrent())return;
    root.innerHTML=`<h3>Payments</h3><p><strong>${esc(money(history.outstandingMinor,s.currency))}</strong> outstanding · ${esc(money(history.paidMinor,s.currency))} recorded</p>${s.status==='cancelled'?'<p>This sale is cancelled. Keep its invoice, credit note and payment history together; arrange any refund through your accounting process.</p>':''}${!history.canRecord&&s.status!=='cancelled'&&s.invoiceNo?'<p class="kv">Another Finance member or Assets admin must record payments for your own purchase.</p>':''}
    ${history.canRecord&&history.outstandingMinor>0n?`<form data-payment><div class="finance-form-grid"><label>Amount · ${esc(s.currency)}<input name="amountMinor" value="${inputMoney(history.outstandingMinor)}" inputmode="decimal" required></label><label>Payment date<input name="paidOn" type="date" value="${today()}" max="${today()}" required></label></div><label>Bank reference<input name="reference" maxlength="200" placeholder="Statement reference (optional)"></label><button class="primary">Review payment</button></form>`:!s.invoiceNo?'<p class="kv">IT issues the invoice after the buyer accepts the offer.</p>':''}
    <div data-payment-review></div><p data-payment-message role="status" aria-live="polite"></p><details ${history.entries.length?'':'hidden'}><summary>Payment history · ${history.entries.length}</summary>${history.entries.map(p=>`<div class="finance-history"><strong>${p.reverses.length?'Correction −':'Payment '}${esc(money(p.amountMinor,s.currency))} · ${esc(p.paidOn)}</strong><p>${esc(p.reference)} ${esc(p.reason)}</p><small>${esc(p.by)} · ${esc(stamp(p.at))}</small>${history.canRecord&&!p.reverses.length&&!history.entries.some(e=>e.reverses[0]===p.id)?` <button class="sm" data-reverse="${p.id}">Correct this entry</button>`:''}</div>`).join('')}</details>${notices.length?`<details><summary>Notifications</summary>${notices.map(n=>`<p>${n.kind==='invoice'?'Finance':'IT'}: ${esc(n.detail)}</p>`).join('')}</details>`:''}`;
    const $=q=>root.querySelector(q),message=t=>$('[data-payment-message]').textContent=t;
    let pending=false;
    function review(input){const reversing=input.reverses.length>0;const requestId=crypto.randomUUID();$('[data-payment-review]').innerHTML=`<div class="card flat"><strong>${reversing?'Reverse':'Record'} ${esc(money(input.amountMinor,s.currency))} on ${esc(input.paidOn)}?</strong><p>${esc(input.reference)} ${esc(input.reason)}</p><button class="primary" data-payment-save>${reversing?'Save correction':'Record payment'}</button><button data-payment-cancel>Keep editing</button></div>`;
      $('[data-payment-cancel]').onclick=()=>{$('[data-payment-review]').replaceChildren();};
      $('[data-payment-save]').onclick=async()=>{if(pending||!isCurrent())return;pending=true;root.querySelectorAll('button,input').forEach(e=>e.disabled=true);try{const r=await api().recordSalePayment(token(),s.id,history.revision,{...input,requestId});if(!r.ok)throw Error(r.detail);await reload();}catch(e){message(errorText(e));root.querySelectorAll('button,input').forEach(e=>e.disabled=false);}finally{pending=false;}};
    }
    if($('[data-payment]'))$('[data-payment]').onsubmit=e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.currentTarget)),amountMinor=minor(f.amountMinor);if(amountMinor===0n||amountMinor>history.outstandingMinor)throw Error('Use an amount up to the outstanding balance.');review({amountMinor,paidOn:f.paidOn,reference:f.reference,reason:'',reverses:[]});}catch(e){message(errorText(e));}};
    root.querySelectorAll('[data-reverse]').forEach(b=>b.onclick=()=>{const p=history.entries.find(p=>p.id===BigInt(b.dataset.reverse));$('[data-payment-review]').innerHTML=`<form data-correction><label>Reason for correcting ${esc(money(p.amountMinor,s.currency))}<input name="reason" maxlength="500" required></label><button>Review correction</button></form>`;$('[data-correction]').onsubmit=e=>{e.preventDefault();review({amountMinor:p.amountMinor,paidOn:p.paidOn,reference:p.reference,reason:new FormData(e.currentTarget).get('reason'),reverses:[p.id]});};});
  }catch(e){if(!isCurrent())return;root.innerHTML=`<h3>Payments</h3><p role="alert">${esc(errorText(e))}</p>`;}
}
